"""Generate first-party editorial pages from curated content and the local product catalog."""
from pathlib import Path
from html import escape as e
from urllib.parse import urlsplit,parse_qs,quote
import json,re
ROOT=Path(__file__).resolve().parents[1];D=ROOT/'dist'
products=json.loads((D/'assets/catalog.json').read_text())
A='<svg aria-hidden="true" viewBox="0 0 24 24"><path d="M4 12h15M13 5l7 7-7 7"/></svg>'
def link(url,label):return f'<a class="text-link" href="{e(url)}">{e(label)} {A}</a>'
def image(name,alt,cls=''):return f'<img class="{cls}" src="/assets/{name}" alt="{e(alt)}" loading="lazy" width="1400" height="1000">'
def card(title,text,url=None,img=None):return f'<article class="story-card">'+(image(img,title) if img else '')+f'<div><h2>{e(title)}</h2><p>{e(text)}</p>'+ (link(url,'Explore') if url else '')+'</div></article>'
def cards(items):return '<div class="story-grid">'+''.join(items)+'</div>'
nav=[('/about/','About'),('/materials/','Materials'),('/designers/','Designers'),('/gallery/','Gallery'),('/sustainability/','Sustainability'),('/corporate/','Corporate'),('/stores/','Find a store'),('/contact/','Contact')]
def page(path,title,kicker,lead,body,hero=None):
 dest=D/path.strip('/')/'index.html';dest.parent.mkdir(parents=True,exist_ok=True)
 content=f'''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>{e(title)} — Uultis</title><meta name="description" content="{e(lead)}"><meta name="theme-color" content="#f3f0ea"><link rel="canonical" href="https://uultis-design-experience.vercel.app/{path.strip('/')}/"><link rel="icon" href="/assets/favicon.svg" type="image/svg+xml"><link rel="stylesheet" href="/explore/pages.css"><script defer src="/explore/pages.js"></script></head><body><a class="skip" href="#content">Skip to content</a><header><a href="/" aria-label="Uultis home"><img src="/assets/logo-black.svg" alt="Uultis" width="110" height="34"></a><nav aria-label="Primary navigation"><a href="/#collection">Collection</a><a href="/room-studio/">Room Studio</a><a href="/stores/">Find a store</a></nav><details class="site-menu"><summary>Explore</summary><nav aria-label="Explore Uultis">{''.join(link(u,l) for u,l in nav)}</nav></details></header><main id="content"><div class="page-heading"><a class="breadcrumb" href="/">UULTIS /</a><span class="eyebrow">{e(kicker)}</span><h1>{e(title)}</h1><p class="lead">{e(lead)}</p></div>{image(hero,title,'page-hero') if hero else ''}<div class="page-body">{body}</div><section class="next-step"><span class="eyebrow">KEEP EXPLORING</span><h2>Find your next<br><em>expression.</em></h2><div>{link('/#collection','Explore the collection')}{link('/room-studio/','Enter the Room Studio')}</div></section></main><footer><img src="/assets/logo-black.svg" alt="Uultis" width="110" height="34"><nav aria-label="Footer navigation">{''.join(link(u,l) for u,l in nav)}{link('/branding/','Branding')}{link('/style-guide/','Style guide')}{link('/privacy/','Privacy & terms')}</nav><p>EXPRESSIONS OF LIFE. / DIGITAL EXPERIENCE CONCEPT</p></footer></body></html>'''
 dest.write_text(content)
page('about','A way of living.','THE UULTIS STORY','Brazilian design shaped by people, materials and the places we call home.',cards([
 card('Design, since 2016.','Uultis brings research and experimentation to furniture for different ways of living. Its collections explore the relationship between comfort, form and individual expression.','/#collection','hero.webp'),
 card('Craft meets technology.','Attention to detail and contemporary production come together in pieces designed to become part of everyday stories.','/materials/','material-wood.webp'),
 card('A shared creative language.','Discover the people behind the pieces, then explore their work in the collection.','/designers/','designer-sergio.webp'),
 card('Considered choices.','From materials to manufacturing, explore the brand’s stated approach to responsible production.','/sustainability/','collection.webp')]))
materials=[('Wood','Natural grain, knots and tonal variation give each piece its own character. Wood brings visual warmth and material strength.','material-wood.webp'),('Fusing glass','Large surfaces combine precision and an artisanal character, adding depth and light to the design.','289-thumb.webp'),('Technological stone','Large-format Italian stone offers varied surface expressions. Finishes include Calacatta Black, Calacatta Michelangelo and Verde Alpi.',None),('Knit fabric','Three-dimensional knitting follows organic forms with continuous surfaces, elasticity and breathability.',None),('Natural marble','White Paraná and black Kouros marble bring distinctive veining, tonal contrast and natural variation.',None),('Technical textiles','Pima Cotton, Thermal Cold and Magma Sense expand the range of tactile and comfort experiences. Confirm specifications for your selected piece.',None)]
page('materials','The character of materials.','MATERIAL / TEXTURE / FORM','A closer look at the surfaces, structures and tactile qualities behind the collection.',cards([card(t,d,None,i) for t,d,i in materials])+'<p class="note">Photography illustrates the material language. Finishes and specifications vary by product; consult its technical sheet.</p>')
page('sustainability','Considered by nature.','MATERIALS & PROCESS','Explore the choices that connect design, production and responsible use of resources.',cards([
 card('Wood sourcing','Uultis prioritizes renewable wood and responsible forest management. Grupo Herval obtained FSC certification for certain products in 2019; this does not mean every item is certified.'),
 card('Foams','Some formulations use soy-based biopolyol. A continuous, closed production process helps reduce material losses, water use and vapor emissions.'),
 card('Packaging & supply','Bulk deliveries, packaging improvements and reuse initiatives aim to reduce discarded material.'),
 card('Facilities','Rainwater reuse, natural light and ventilation, efficient lighting and thermal insulation support more efficient resource use.'),
 card('Recovery & reuse','Wood residues can be reused for energy. Uultis reports participation in ASLORE since 2021 to support reverse logistics and packaging recycling.'),
 card('Choose with information','Check the material, finish and technical requirements of the specific product you are considering.','/#collection')]))
page('corporate','Spaces that bring people together.','DESIGN FOR PROFESSIONAL LIFE','Furniture for environments where comfort, identity and everyday function meet.',cards([
 card('Hospitality & shared spaces','Explore seating, tables and complementary pieces for a considered furniture selection.','/#collection','gallery-dafne.webp'),
 card('From a piece to a project','Compare dimensions and technical sheets in each product page. Use the Room Studio to explore selected design studies.','/room-studio/','gallery-niva.webp'),
 card('Talk through the brief','Share your project type, location and selected products with the Uultis team to discuss availability and specifications.','/contact/','collection.webp')])+'<div class="prose"><h2>Selected corporate references</h2><p>The brand’s corporate portfolio includes Swan Generation, Carrano, Costa, Starbucks, Jangal das Araucárias and Laghetto properties.</p>'+link('/contact/','Find a representative')+'</div>')
# Keep product authorship connected to a real, local selection of pieces.
authors={}
for p in products:
 u=p.get('designer_url','');q=parse_qs(urlsplit(u).query);id=q.get('designer',[''])[0]
 if not id:
  m=re.search(r'/designers/(\d+)/',u);id=m.group(1) if m else ''
 if id:authors.setdefault(id,{'name':p['designer'],'products':[]})['products'].append(p)
def product_cards(items):
 return '<div class="product-grid">'+''.join(f'<article><a href="/#product/{e(p["id"])}">'+image(p['thumbnail'].split('/')[-1],p['name'])+f'<span class="eyebrow">{e(p["category"])}</span><h2>{e(p["name"])}</h2></a></article>' for p in items)+'</div>'
designer_cards=[]
for id,a in sorted(authors.items(),key=lambda x:x[1]['name']):
 portrait={'6':'designer-sergio.webp','10':'designer-artur.webp'}.get(id)
 pic=portrait or a['products'][0]['thumbnail'].split('/')[-1]
 designer_cards.append(card(a['name'],f'{len(a["products"])} pieces in the collection.',f'/designers/{id}/',pic))
 page(f'designers/{id}',a['name'],'BEHIND THE DESIGN',f'Explore {len(a["products"])} pieces credited to {a["name"]} in the Uultis collection.',('<p class="note">'+link('/designers/','All designers')+'</p>')+product_cards(a['products']),portrait)
page('designers','Different perspectives.','PEOPLE BEHIND THE PIECES','Meet the designers through their work. Each collection brings another perspective on form, materials and the way we live.',cards(designer_cards)+'<p class="note">Cards show portraits where available and a selected product for the other designers.</p>')
galleries=[('70','Casa D|A','Niva ARQ','gallery-niva.webp','Architecture, natural light and contemporary furniture come together in a spacious residential interior. The project by Niva Arquitetura brings comfort and a welcoming material palette to the living spaces.'),('71','Dafne Beauty House','Paula Ambrósio','gallery-dafne.webp','A beauty space in Midtown Miami brings together contemporary architecture, biophilic design and natural materials. Soft curves, considered lighting and Brazilian furniture support a welcoming, fluid experience.')]
for id,name,credit,img,description in galleries:
 page('gallery/'+id,name,'A PROJECT BY '+credit.upper(),description,f'<div class="prose"><h2>Design in context.</h2><p>Project credit: {e(credit)}. Photography from the Uultis project collection.</p>{link("/gallery/","Back to the gallery")}{link("/contact/","Discuss a project")}</div>',img)
page('gallery','Spaces with soul.','DESIGN IN REAL LIFE','Explore interiors where architecture, materials and furniture become part of the same story.',cards([card(name,credit,'/gallery/'+id+'/',img) for id,name,credit,img,_ in galleries]))
# Public directory details retain their source spelling and local contact formats.
directory=json.loads((ROOT/'scripts/directory-data.json').read_text());entries=[]
for row in directory:
 paragraphs=[]
 for detail in row['details']:
  if not detail or detail=='.':continue
  text=e(detail)
  text=re.sub(r'([\w.+-]+@[\w.-]+\.[A-Za-z]{2,})',r'<a href="mailto:\1">\1</a>',text)
  paragraphs.append('<p>'+text+'</p>')
 paragraphs.append(link('/contact/','Enquire through Uultis'))
 label='Showroom' if row['type']=='store' else 'Representative'
 location=' · '.join(filter(None,[row['city'],row['state'],row['country']]))
 entries.append(f'<article class="directory-card" data-kind="{row["type"]}" data-country="{row["country"]}" data-state="{row["state"]}"><span class="eyebrow">{label} / {e(location)}</span><h2>{e(row["name"])}</h2>'+''.join(paragraphs)+'</article>')
filters='''<form class="directory-filters" role="search"><label>Search city, state, name or region<input id="directory-search" type="search" placeholder="Miami, São Paulo, RS…"></label><label>Type<select id="directory-type"><option value="all">All locations</option><option value="store">Showrooms</option></select></label><label>Country<select id="directory-country"><option value="all">All countries</option><option value="BR">Brazil</option><option value="US">United States</option><option value="NL">Netherlands</option></select></label></form><p id="directory-count" role="status"></p>'''
page('stores','Find your place.','SHOWROOMS','Find a showroom and plan your next conversation with the Uultis team.',filters+'<div class="directory-grid">'+''.join(entries)+'</div><p id="directory-empty" hidden>No matching locations. Try a different city or contact the Uultis team.</p><p class="note">Public directory checked on October 20, 2026. Confirm hours, availability and visiting arrangements through the Uultis team. For regional representative enquiries, use the central contact channel.</p>'+link('/contact/','Contact Uultis'))
page('contact','Let’s start a conversation.','CONTACT UULTIS','Questions about a piece, a finish or a project? Get in touch with the team.',cards([
 card('Email','contato@uultis.com','mailto:contato@uultis.com'),card('Telephone','+55 51 3564 8382','tel:+555135648382'),card('Address','BR 116, KM 223.5 · Dois Irmãos · RS · Brazil','/stores/')])+'''<div class="contact-layout"><div class="prose"><h2>Your next project,<br>in a few words.</h2><p>Prepare an enquiry with the details that matter. This form opens a draft in your email app for you to review and send.</p></div><form id="contact-form"><label>Your name<input name="name" autocomplete="name" required maxlength="100"></label><label>Your email<input name="email" type="email" autocomplete="email" required maxlength="150"></label><label>City / country<input name="location" autocomplete="address-level2" maxlength="150"></label><label>What can we help with?<select name="subject"><option>Product enquiry</option><option>Corporate project</option><option>Technical information</option><option>Other enquiry</option></select></label><label>Message<textarea name="message" rows="5" required maxlength="3000"></textarea></label><button class="button" type="submit">Open email draft</button><p class="note" id="contact-status" role="status">Nothing is sent automatically.</p></form></div>''')
page('privacy','Privacy & terms.','THIS DIGITAL EXPERIENCE','How this version of the website handles your choices and project enquiries.','''<div class="prose"><h2>Your selection</h2><p>Favorite products are stored in your browser’s local storage on this device. They are not an account or a shared customer record. Remove individual favorites in My selection or clear this site’s browser data to erase them.</p><h2>Contact</h2><p>The enquiry form prepares an email draft. You review and send it through your email service. This site does not submit that form to a customer database.</p><h2>Files and embedded media</h2><p>Technical documents may be delivered from the manufacturer’s file service through this domain. Product videos and external modeling services use their own providers. Loading them can disclose network information, such as your IP address, to those providers. Hosting also involves the technical processing needed to deliver this site.</p><h2>Product information</h2><p>Photography, names and design credits remain the property of their respective owners. This is a digital experience concept. Confirm availability, materials and specifications before purchase. The Room Studio contains approximate design studies, not manufacturer CAD files.</p><h2>Questions</h2><p>For product enquiries, use the contact page. For privacy questions about your email service or browser, consult that provider’s controls.</p>'''+link('/contact/','Contact')+'</div>')
print('Generated editorial pages,',len(authors),'designer pages and',len(directory),'directory entries')
